            { "AssetPreview", "Utility for fetching asset previews by instance ID of assets, See AssetPreview.GetAssetPreview. Since previews are loaded asynchronously methods are provided for requesting if all previews have been fully loaded, see AssetPreview.IsLoadingAssetPreviews. Loaded previews are stored in a cache, the size of the cache can be controlled by calling [AssetPreview.SetPreviewTextureCacheSize]." },
            { "AssetPreview.GetAssetPreview", "Returns a preview texture for an asset." },
            { "AssetPreview.GetMiniThumbnail", "Returns the thumbnail for an object (like the ones you see in the project view)." },
            { "AssetPreview.GetMiniTypeThumbnail", "Returns the thumbnail for the type." },
            { "AssetPreview.IsLoadingAssetPreview", "Loading previews is asynchronous so it is useful to know if a specific asset preview is in the process of being loaded so client code e.g can repaint while waiting for the loading to finish." },
            { "AssetPreview.IsLoadingAssetPreviews", "Loading previews is asynchronous so it is useful to know if any requested previews are in the process of being loaded so client code e.g can repaint while waiting." },
            { "AssetPreview.SetPreviewTextureCacheSize", "Set the asset preview cache to a size that can hold all visible previews on the screen at once." },
            { "AssetSettingsProvider", "AssetSettingsProvider is a specialization of the SettingsProvider class that converts legacy settings to Unified Settings. Legacy settings include any settings that used the Inspector to modify themselves, such as the *.asset files under the ProjectSettings folder. Under the hood, AssetSettingsProvider creates an Editor for specific Assets and builds the UI for the Settings window by wrapping the Editor.OnInspectorGUI function.Internally we use this class to wrap our existing settings." },
            { "AssetSettingsProvider-settingsEditor", "Editor providing UI to modify the settings." },
            { "AssetSettingsProvider.CreateProviderFromAssetPath", "Create an AssetSettingsProvider from an asset path." },
            { "AssetSettingsProvider.CreateProviderFromObject", "Create an AssetSettingsProvider from a settings object." },
            { "AssetSettingsProvider.CreateProviderFromResourcePath", "Create an AssetSettingsProvider from an asset resource path." },
            { "AssetSettingsProvider-ctor", "Creates a new AssetSettingsProvider so you can wrap legacy settings (that is, settings that previously appeared in the Inspector)." },
            { "AssetSettingsProvider.OnActivate", "Overrides SettingsProvider.OnActivate for this AssetSettingsProvider." },
            { "AssetSettingsProvider.OnDeactivate", "Overrides SettingsProvider.OnDeactivate for this AssetSettingsProvider." },
            { "AssetSettingsProvider.OnFooterBarGUI", "Overrides SettingsProvider.OnFooterBarGUI for this AssetSettingsProvider." },
            { "AssetSettingsProvider.OnGUI", "Overrides SettingsProvider.OnGUI for this AssetSettingsProvider." },
            { "AssetSettingsProvider.OnTitleBarGUI", "Overrides SettingsProvider.OnTitleBarGUI for this AssetSettingsProvider. This draws the button bar that contains the add to preset and the help buttons." },
            { "AsyncOperation", "Asynchronous operation coroutine." },
            { "AsyncOperation-allowSceneActivation", "Allow Scenes to be activated as soon as it is ready." },
            { "AsyncOperation-completed", "Event that is invoked upon operation completion.  An event handler that is registered in the same frame as the call that creates it will be invoked next frame, even if the operation is able to complete synchronously.  If a handler is registered after the operation has completed and has already invoked the complete event, the handler will be called synchronously." },
            { "AsyncOperation-isDone", "Has the operation finished? (Read Only)" },
            { "AsyncOperation-priority", "Priority lets you tweak in which order async operation calls will be performed." },
            { "AsyncOperation-progress", "What's the operation's progress. (Read Only)" },
