            { "ContactFilter2D", "A set of parameters for filtering contact results. Define the angle by referring to their position in world space, where 0 degrees is parallel to the positive x-axis, 90 degrees is parallel to the positive y-axis, 180 degrees is parallel to the negative x-axis, and 270 degrees is parallel to the negative y-axis." },
            { "ContactFilter2D-isFiltering", "Given the current state of the contact filter, determine whether it would filter anything." },
            { "ContactFilter2D-layerMask", "Sets the contact filter to filter the results that only include Collider2D on the layers defined by the layer mask." },
            { "ContactFilter2D-maxDepth", "Sets the contact filter to filter the results to only include Collider2D with a Z coordinate (depth) less than this value." },
            { "ContactFilter2D-maxNormalAngle", "Sets the contact filter to filter the results to only include contacts with collision normal angles that are less than this angle." },
            { "ContactFilter2D-minDepth", "Sets the contact filter to filter the results to only include Collider2D with a Z coordinate (depth) greater than this value." },
            { "ContactFilter2D-minNormalAngle", "Sets the contact filter to filter the results to only include contacts with collision normal angles that are greater than this angle." },
            { "ContactFilter2D-useDepth", "Sets the contact filter to filter the results by depth using minDepth and maxDepth." },
            { "ContactFilter2D-useLayerMask", "Sets the contact filter to filter results by layer mask." },
            { "ContactFilter2D-useNormalAngle", "Sets the contact filter to filter the results by the collision's normal angle using minNormalAngle and maxNormalAngle." },
            { "ContactFilter2D-useOutsideDepth", "Sets the contact filter to filter within the minDepth and maxDepth range, or outside that range." },
            { "ContactFilter2D-useOutsideNormalAngle", "Sets the contact filter to filter within the minNormalAngle and maxNormalAngle range, or outside that range." },
            { "ContactFilter2D-useTriggers", "Sets to filter contact results based on trigger collider involvement." },
            { "ContactFilter2D.ClearDepth", "Turns off depth filtering by setting useDepth to false.  The associated values of minDepth and maxDepth are not changed." },
            { "ContactFilter2D.ClearLayerMask", "Turns off layer mask filtering by setting useLayerMask to false.  The associated value of layerMask is not changed." },
            { "ContactFilter2D.ClearNormalAngle", "Turns off normal angle filtering by setting useNormalAngle to false. The associated values of minNormalAngle and maxNormalAngle are not changed." },
            { "ContactFilter2D.IsFilteringDepth", "Checks if the Transform for obj is within the depth range to be filtered." },
            { "ContactFilter2D.IsFilteringLayerMask", "Checks if the GameObject.layer for obj is included in the layerMask to be filtered." },
            { "ContactFilter2D.IsFilteringNormalAngle", "Checks if the angle of normal is within the normal angle range to be filtered." },
            { "ContactFilter2D.IsFilteringTrigger", "Checks if the collider is a trigger and should be filtered by the useTriggers to be filtered." },
            { "ContactFilter2D.NoFilter", "Sets the contact filter to not filter any ContactPoint2D." },
