            { "Experimental.Rendering.GraphicsFormat", "Use this format to create either Textures or RenderTextures from scripts." },
            { "Experimental.Rendering.GraphicsFormat.A10R10G10B10_XRSRGBPack32", "A four-component, 64-bit packed unsigned normalized format that has a 10-bit A component in bits 30..39, a 10-bit R component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit B component in bits 0..9. The components are gamma encoded and their values range from -0.5271 to 1.66894. The alpha component is clamped to either 0.0 or 1.0 on sampling, rendering, and writing operations." },
            { "Experimental.Rendering.GraphicsFormat.A10R10G10B10_XRUNormPack32", "A four-component, 64-bit packed unsigned normalized format that has a 10-bit A component in bits 30..39, a 10-bit R component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit B component in bits 0..9. The components are linearly encoded and their values range from -0.752941 to 1.25098 (pre-expansion). The alpha component is clamped to either 0.0 or 1.0 on sampling, rendering, and writing operations." },
            { "Experimental.Rendering.GraphicsFormat.A1R5G5B5_UNormPack16", "A four-component, 16-bit packed unsigned normalized format that has a 1-bit A component in bit 15, a 5-bit R component in bits 10..14, a 5-bit G component in bits 5..9, and a 5-bit B component in bits 0..4." },
            { "Experimental.Rendering.GraphicsFormat.A2B10G10R10_SIntPack32", "A four-component, 32-bit packed signed integer format that has a 2-bit A component in bits 30..31, a 10-bit B component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit R component in bits 0..9." },
            { "Experimental.Rendering.GraphicsFormat.A2B10G10R10_UIntPack32", "A four-component, 32-bit packed unsigned integer format that has a 2-bit A component in bits 30..31, a 10-bit B component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit R component in bits 0..9." },
            { "Experimental.Rendering.GraphicsFormat.A2B10G10R10_UNormPack32", "A four-component, 32-bit packed unsigned normalized format that has a 2-bit A component in bits 30..31, a 10-bit B component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit R component in bits 0..9." },
            { "Experimental.Rendering.GraphicsFormat.A2R10G10B10_SIntPack32", "A four-component, 32-bit packed signed integer format that has a 2-bit A component in bits 30..31, a 10-bit R component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit B component in bits 0..9." },
            { "Experimental.Rendering.GraphicsFormat.A2R10G10B10_UIntPack32", "A four-component, 32-bit packed unsigned integer format that has a 2-bit A component in bits 30..31, a 10-bit R component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit B component in bits 0..9." },
            { "Experimental.Rendering.GraphicsFormat.A2R10G10B10_UNormPack32", "A four-component, 32-bit packed unsigned normalized format that has a 2-bit A component in bits 30..31, a 10-bit R component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit B component in bits 0..9." },
            { "Experimental.Rendering.GraphicsFormat.A2R10G10B10_XRSRGBPack32", "A four-component, 32-bit packed unsigned normalized format that has a 2-bit A component in bits 30..31, a 10-bit R component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit B component in bits 0..9. The components are gamma encoded and their values range from -0.5271 to 1.66894. The alpha component is clamped to either 0.0 or 1.0 on sampling, rendering, and writing operations." },
            { "Experimental.Rendering.GraphicsFormat.A2R10G10B10_XRUNormPack32", "A four-component, 32-bit packed unsigned normalized format that has a 2-bit A component in bits 30..31, a 10-bit R component in bits 20..29, a 10-bit G component in bits 10..19, and a 10-bit B component in bits 0..9. The components are linearly encoded and their values range from -0.752941 to 1.25098 (pre-expansion). The alpha component is clamped to either 0.0 or 1.0 on sampling, rendering, and writing operations." },
            { "Experimental.Rendering.GraphicsFormat.B10G11R11_UFloatPack32", "A three-component, 32-bit packed unsigned floating-point format that has a 10-bit B component in bits 22..31, an 11-bit G component in bits 11..21, an 11-bit R component in bits 0..10." },
            { "Experimental.Rendering.GraphicsFormat.B4G4R4A4_UNormPack16", "A four-component, 16-bit packed unsigned normalized format that has a 4-bit B component in bits 12..15, a 4-bit G component in bits 8..11, a 4-bit R component in bits 4..7, and a 4-bit A component in bits 0..3." },
            { "Experimental.Rendering.GraphicsFormat.B5G5R5A1_UNormPack16", "A four-component, 16-bit packed unsigned normalized format that has a 5-bit B component in bits 11..15, a 5-bit G component in bits 6..10, a 5-bit R component in bits 1..5, and a 1-bit A component in bit 0." },
            { "Experimental.Rendering.GraphicsFormat.B5G6R5_UNormPack16", "A three-component, 16-bit packed unsigned normalized format that has a 5-bit B component in bits 11..15, a 6-bit G component in bits 5..10, and a 5-bit R component in bits 0..4." },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8_SInt", "A three-component, 24-bit signed integer format that has an 8-bit B component in byte 0, an 8-bit G component in byte 1, and an 8-bit R component in byte 2." },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8_SNorm", "A three-component, 24-bit signed normalized format that has an 8-bit B component in byte 0, an 8-bit G component in byte 1, and an 8-bit R component in byte 2." },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8_SRGB", "A three-component, 24-bit unsigned normalized format that has an 8-bit R component stored with sRGB nonlinear encoding in byte 0, an 8-bit G component stored with sRGB nonlinear encoding in byte 1, and an 8-bit B component stored with sRGB nonlinear encoding in byte 2." },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8_UInt", "A three-component, 24-bit unsigned integer format that has an 8-bit B component in byte 0, an 8-bit G component in byte 1, and an 8-bit R component in byte 2" },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8_UNorm", "A three-component, 24-bit unsigned normalized format that has an 8-bit B component in byte 0, an 8-bit G component in byte 1, and an 8-bit R component in byte 2." },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8A8_SInt", "A four-component, 32-bit signed integer format that has an 8-bit B component in byte 0, an 8-bit G component in byte 1, an 8-bit R component in byte 2, and an 8-bit A component in byte 3." },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8A8_SNorm", "A four-component, 32-bit signed normalized format that has an 8-bit B component in byte 0, an 8-bit G component in byte 1, an 8-bit R component in byte 2, and an 8-bit A component in byte 3." },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8A8_SRGB", "A four-component, 32-bit unsigned normalized format that has an 8-bit B component stored with sRGB nonlinear encoding in byte 0, an 8-bit G component stored with sRGB nonlinear encoding in byte 1, an 8-bit R component stored with sRGB nonlinear encoding in byte 2, and an 8-bit A component in byte 3." },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8A8_UInt", "A four-component, 32-bit unsigned integer format that has an 8-bit B component in byte 0, an 8-bit G component in byte 1, an 8-bit R component in byte 2, and an 8-bit A component in byte 3." },
            { "Experimental.Rendering.GraphicsFormat.B8G8R8A8_UNorm", "A four-component, 32-bit unsigned normalized format that has an 8-bit B component in byte 0, an 8-bit G component in byte 1, an 8-bit R component in byte 2, and an 8-bit A component in byte 3." },
            { "Experimental.Rendering.GraphicsFormat.D16_UNorm", "A one-component, 16-bit unsigned normalized format that has a single 16-bit depth component." },
            { "Experimental.Rendering.GraphicsFormat.D24_UNorm", "A two-component, 32-bit format that has 24 unsigned normalized bits in the depth component and, optionally: 8 bits that are unused." },
            { "Experimental.Rendering.GraphicsFormat.D24_UNorm_S8_UInt", "A two-component, 32-bit packed format that has 8 unsigned integer bits in the stencil component, and 24 unsigned normalized bits in the depth component." },
            { "Experimental.Rendering.GraphicsFormat.D32_SFloat", "A one-component, 32-bit signed floating-point format that has 32-bits in the depth component." },
            { "Experimental.Rendering.GraphicsFormat.D32_SFloat_S8_Uint", "A two-component format that has 32 signed float bits in the depth component and 8 unsigned integer bits in the stencil component. There are optionally: 24-bits that are unused." },
            { "Experimental.Rendering.GraphicsFormat.DepthAuto", "Automatic format used for Depth buffers (Platform dependent)" },
            { "Experimental.Rendering.GraphicsFormat.E5B9G9R9_UFloatPack32", "A three-component, 32-bit packed unsigned floating-point format that has a 5-bit shared exponent in bits 27..31, a 9-bit B component mantissa in bits 18..26, a 9-bit G component mantissa in bits 9..17, and a 9-bit R component mantissa in bits 0..8." },
            { "Experimental.Rendering.GraphicsFormat.None", "The format is not specified." },
