            { "LightingSettings", "An object containing settings for precomputing lighting data, that Unity can serialize as a Lighting Settings Asset." },
            { "LightingSettings-albedoBoost", "The intensity of surface albedo throughout the Scene when considered in lighting calculations. This value influences the energy of light at each bounce. (Editor only)." },
            { "LightingSettings-ao", "Whether to apply ambient occlusion to lightmaps. (Editor only)." },
            { "LightingSettings-aoExponentDirect", "Determines the degree to which direct lighting is considered when calculating ambient occlusion in lightmaps. (Editor only)." },
            { "LightingSettings-aoExponentIndirect", "Sets the contrast of ambient occlusion that Unity applies to indirect lighting in lightmaps. (Editor only)." },
            { "LightingSettings-aoMaxDistance", "The distance that a ray travels before Unity considers it to be unoccluded when calculating ambient occlusion in lightmaps. (Editor only)." },
            { "LightingSettings-autoGenerate", "Whether the Unity Editor automatically precomputes lighting data when the Scene data changes. (Editor only)." },
            { "LightingSettings-bakedGI", "Whether to enable the Baked Global Illumination system for this Scene." },
            { "LightingSettings-bounces", "This property is now obsolete. Use LightingSettings.maxBounces." },
            { "LightingSettings-compressLightmaps", "Whether to compress the lightmap textures that the Progressive Lightmapper generates. (Editor only)" },
            { "LightingSettings-denoiserTypeAO", "Determines the type of denoising that the Progressive Lightmapper applies to ambient occlusion in lightmaps. (Editor only)." },
            { "LightingSettings-denoiserTypeDirect", "Determines the denoiser that the Progressive Lightmapper applies to direct lighting. (Editor only)." },
            { "LightingSettings-denoiserTypeIndirect", "Determines the denoiser that the Progressive Lightmapper applies to indirect lighting. (Editor only)." },
            { "LightingSettings-directionalityMode", "Determines whether the lightmapper should generate directional or non-directional lightmaps. (Editor only)." },
            { "LightingSettings-directSampleCount", "Specifies the number of samples the Progressive Lightmapper uses for direct lighting calculations. (Editor only)." },
            { "LightingSettings-environmentSampleCount", "Specifies the number of samples the Progressive Lightmapper uses when sampling indirect lighting from the skybox. (Editor only)." },
            { "LightingSettings-exportTrainingData", "Whether the Progressive Lightmapper exports machine learning training data to the Project folder when it performs the bake. ( Editor only)." },
            { "LightingSettings-extractAO", "Whether the Progressive Lightmapper extracts Ambient Occlusion to a separate lightmap. (Editor only)." },
            { "LightingSettings-filteringAtrousPositionSigmaAO", "Specifies the threshold the Progressive Lightmapper uses to filter direct light stored in the lightmap when using the A-Trous filter. (Editor only)." },
            { "LightingSettings-filteringAtrousPositionSigmaDirect", "Specifies the threshold the Progressive Lightmapper uses to filter the indirect lighting component of the lightmap when using the A-Trous filter. (Editor only)." },
            { "LightingSettings-filteringAtrousPositionSigmaIndirect", "Specifies the radius the Progressive Lightmapper uses to filter the ambient occlusion component in the lightmap when using Gaussian filter. (Editor only)." },
            { "LightingSettings-filteringGaussRadiusAO", "Specifies the radius the Progressive Lightmapper uses to filter the direct lighting component of the lightmap when using Gaussian filter. (Editor only)." },
            { "LightingSettings-filteringGaussRadiusDirect", "Specifies the radius the Progressive Lightmapper used to filter the indirect lighting component of the lightmap when using Gaussian filter. (Editor only)." },
            { "LightingSettings-filteringGaussRadiusIndirect", "Specifies the method used by the Progressive Lightmapper to reduce noise in lightmaps. (Editor only)." },
            { "LightingSettings-filteringMode", "Specifies the filter type that the Progressive Lightmapper uses for ambient occlusion. (Editor only)." },
            { "LightingSettings-filterTypeAO", "Specifies the filter kernel that the Progressive Lightmapper uses for ambient occlusion. (Editor only)." },
            { "LightingSettings-filterTypeDirect", "Specifies the filter kernel that the Progressive Lightmapper uses for the direct lighting. (Editor only)." },
            { "LightingSettings-filterTypeIndirect", "Specifies the filter kernel that the Progressive Lightmapper uses for indirect lighting. (Editor only)." },
            { "LightingSettings-finalGather", "Specifies whether the final light bounce of the global illumination calculation is calculated at the same resolution as the baked lightmap. (Editor only)." },
            { "LightingSettings-finalGatherFiltering", "Controls whether a denoising filter is applied to the final gather output." },
            { "LightingSettings-finalGatherRayCount", "Controls the number of rays emitted for every final gather point. A final gather point is a lightmap texel in the final, composited lightmap. (Editor only)." },
            { "LightingSettings-indirectResolution", "Defines the number of texels that Enlighten uses per world unit when calculating indirect lighting. (Editor only)." },
            { "LightingSettings-indirectSampleCount", "Specifies the number of samples the Progressive Lightmapper uses for indirect lighting calculations. (Editor only)." },
            { "LightingSettings-indirectScale", "Multiplies the intensity of of indirect lighting in lightmaps. (Editor only)." },
            { "LightingSettings-lightmapMaxSize", "The maximum size in pixels of an individual lightmap texture. (Editor only)." },
            { "LightingSettings-lightmapPadding", "Sets the distance (in texels) between separate UV tiles in lightmaps. (Editor only)." },
            { "LightingSettings-lightmapper", "Determines which backend to use for baking lightmaps in the Baked Global Illumination system. (Editor only)." },
            { "LightingSettings-lightmapResolution", "Defines the number of texels to use per world unit when generating lightmaps." },
            { "LightingSettings-lightProbeSampleCountMultiplier", "Specifies the number of samples to use for Light Probes relative to the number of samples for lightmap texels. (Editor only)." },
            { "LightingSettings-maxBounces", "Stores the maximum number of bounces the Progressive Lightmapper computes for indirect lighting. (Editor only)" },
            { "LightingSettings-minBounces", "Stores the minimum number of bounces the Progressive Lightmapper computes for indirect lighting. (Editor only)" },
            { "LightingSettings-mixedBakeMode", "Sets the MixedLightingMode that Unity uses for all Mixed Lights in the Scene. (Editor only)." },
            { "LightingSettings-prioritizeView", "Whether the Progressive Lightmapper prioritizes baking visible texels within the frustum of the Scene view. (Editor only)." },
