            { "Networking.GlobalConfig.MinTimerTimeout", "Defines the minimum timeout in milliseconds recognised by the system. The default value is 1 ms." },
            { "Networking.GlobalConfig.NetworkEventAvailable", "Defines the callback delegate which you can use to get a notification when the host (defined by hostID) has a network event. The callback is called for all event types except Networking.NetworkEventType.Nothing.See Also: Networking.NetworkEventType" },
            { "Networking.GlobalConfig.ReactorMaximumReceivedMessages", "This property determines the initial size of the queue that holds messages received by Unity Multiplayer before they are processed." },
